1	#!/bin/bash
2	# GSM8K eval (before) -> GRPO -> GSM8K eval (after). Paths relative to this workspace.
3	set -uo pipefail
4	cd "$(dirname "$0")"
5	MODEL=${MODEL:-models/Qwen2.5-1.5B-Instruct}
6	OUTPUT_DIR=${OUTPUT_DIR:-outputs/grpo}
7	export LOG_DIR=${LOG_DIR:-results}
8	MAX_STEPS=${MAX_STEPS:-200}; LR=${LEARNING_RATE:-1e-5}; SEED=${SEED:-20261120}; SKIP_EVAL=${SKIP_EVAL:-0}
9	export HF_HUB_OFFLINE=1 HF_DATASETS_OFFLINE=1 TRANSFORMERS_OFFLINE=1 TOKENIZERS_PARALLELISM=false
10	mkdir -p "$LOG_DIR"
11	if [ "$SKIP_EVAL" != 1 ]; then
12	  python eval_gsm8k.py --model "$MODEL" --step 0 --out "$LOG_DIR/eval_before.json" > "$LOG_DIR/eval_before.log" 2>&1 || { tail -30 "$LOG_DIR/eval_before.log"; exit 1; }
13	  cat "$LOG_DIR/eval_before.json"; echo; grep "^eval 0:" "$LOG_DIR/eval_before.log"
14	fi
15	python train_grpo.py --model "$MODEL" --output "$OUTPUT_DIR" --max-steps "$MAX_STEPS" --learning-rate "$LR" --seed "$SEED" > "$LOG_DIR/train.log" 2>&1
16	rc=$?; echo "train_grpo.py exit=$rc"; [ $rc -eq 0 ] || { tail -40 "$LOG_DIR/train.log"; exit $rc; }
17	if [ "$SKIP_EVAL" != 1 ]; then
18	  python eval_gsm8k.py --model "$OUTPUT_DIR" --step "$MAX_STEPS" --out "$LOG_DIR/eval_after.json" > "$LOG_DIR/eval_after.log" 2>&1 || { tail -30 "$LOG_DIR/eval_after.log"; exit 1; }
19	  cat "$LOG_DIR/eval_after.json"; echo; grep "^eval $MAX_STEPS:" "$LOG_DIR/eval_after.log"
20	fi
21

